create or replace function public.gamification_activity_trigger() returns trigger language plpgsql security definer set search_path='public','auth','extensions','pg_temp' as $function$ declare v_result jsonb; v_eligible boolean:=true; begin if new.user_id is null then return new; end if; if tg_table_name='reviews' then if new.check_in_id is not null then v_eligible:=public.is_qualifying_return_visit(new.user_id,new.location_id,(select checked_in_at from public.check_ins where id=new.check_in_id)); else v_eligible:=false; end if; if not v_eligible then return new; end if; end if; perform public.record_gamification_activity(case when tg_table_name='reviews' then 'review' else 'check_in' end,new.id); return new; end; $function$;
comment on function public.gamification_activity_trigger() is 'Canonical gamification trigger. Reviews remain fully recordable, but review rewards require a qualifying return visit and the shared daily progression cap.';
